main / used: none / 1x1 / progress: custom(step: 5lb, type: 0) {~
  if (week < 6) {
    if (week == 5 && minReps[1] == 1) {
      if (completedReps[1] >= 2) {
        rm1 = completedWeights[1] * (1 + 0.03 * (min(completedReps[1], 4) - 1))
      } else if (completedReps[1] < 1) {
        rm1 = rm1 * 0.975
      }
    } else if (!(completedReps >= minReps)) {
      rm1 = rm1 * 0.975
    }
  }
~} / update: custom() {~
  // type: 1 - squat, 2 - bench press, 3 - deadlift
  if (setIndex == 0) {
    if (state.type == 1) {
      if (week == 2 && dayInWeek == 1) {
        for (var.i in weights) {
          if (var.i > 1) {
            weights[var.i] += state.step
          }
        }
      } else if ((week == 2 && dayInWeek == 3) || (week == 4 && dayInWeek == 3)) {
        weights[1] += state.step
      } else if (week == 3 && dayInWeek == 1) {
        weights += state.step
      } else if (week == 3 && dayInWeek == 3) {
        weights += 2 * state.step
      } else if (week == 4 && dayInWeek == 1) {
        weights[1] -= state.step
        weights[3] += state.step
      }
    } else if (state.type == 2) {
      if (week == 2 && (dayInWeek == 2 || dayInWeek == 4)) {
        weights[3] += state.step
      } else if (week == 2 && dayInWeek == 5) {
        weights -= state.step
      } else if (week == 3 && dayInWeek == 4) {
        weights += state.step
      } else if (week == 4 && dayInWeek == 2) {
        weights[1] -= state.step
        weights[2] -= state.step
      }
    } else if (state.type == 3) {
      if (week == 4 && dayInWeek == 3) {
        weights[1] += state.step
      }
    }
  }
  if (state.type == 1 && week == 2 && dayInWeek == 3 && setIndex == 1) {
    if (completedReps[1] >= 10) {
      numberOfSets = 11
    } else if (completedReps[1] >= 8) {
      numberOfSets = 9
    } else if (completedReps[1] >= 7) {
      numberOfSets = 6
    } else {
      numberOfSets = 1
    }
    if (numberOfSets > 1) {
      sets(2, numberOfSets, 3, 3, 0, weights[1] - 2 * state.step, 60, 0, 0)
    }
  }
~}
